<!DOCTYPE html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The One Dev Hub</title>
<style>
:root{--bg:#0a0d12;--panel:#111722;--panel2:#171f2d;--line:#283447;--text:#f5f7fb;--muted:#91a0b7;--accent:#6c8cff;--accent2:#86e1ff;--ok:#48d597;--warn:#ffbf5f;--danger:#ff6b75}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#090c11,#0d121a);color:var(--text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;height:100vh;overflow:hidden}button,textarea{font:inherit}.app{height:100vh;display:grid;grid-template-rows:72px 1fr}.top{display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-bottom:1px solid var(--line);background:rgba(10,13,18,.94)}.brand{display:flex;align-items:center;gap:13px}.mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent2));display:grid;place-items:center;color:#07111c;font-weight:1000}.brand h1{font-size:18px;margin:0}.brand small{color:var(--muted)}.actions{display:flex;gap:8px;align-items:center}.btn{border:1px solid var(--line);color:var(--text);background:#151c28;border-radius:10px;padding:9px 12px;cursor:pointer;font-weight:750}.btn:hover{border-color:#4b5e7d}.btn.primary{background:linear-gradient(135deg,#607cff,#4c6df2);border-color:#7189ff}.btn.ok{background:#173426;border-color:#295d43;color:#9af1c2}.layout{display:grid;grid-template-columns:230px 330px 1fr;min-height:0}.sidebar,.files{border-right:1px solid var(--line);background:#0e131c;overflow:auto}.sidebar{padding:18px 13px}.section-label{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:#68788f;margin:4px 10px 10px}.project{width:100%;border:1px solid transparent;background:transparent;color:var(--text);border-radius:11px;padding:12px;text-align:left;cursor:pointer;display:flex;align-items:center;gap:10px;margin-bottom:6px}.project:hover,.project.active{background:#171f2d;border-color:#2b3850}.ico{width:34px;height:34px;border-radius:9px;background:#202b3d;display:grid;place-items:center}.sidebar-footer{margin-top:22px;padding:12px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.files{padding:15px}.crumb{display:flex;gap:7px;align-items:center;min-height:36px;color:var(--muted);font-size:13px;margin-bottom:8px}.file-row{display:flex;align-items:center;gap:9px;padding:9px;border-radius:9px;cursor:pointer;color:#dbe3ef}.file-row:hover{background:#192232}.file-row.folder{color:#d9c787}.file-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-size{margin-left:auto;color:#60708a;font-size:11px}.editor{min-width:0;display:grid;grid-template-rows:52px 1fr 32px;background:#0b1017}.editor-head{display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid var(--line);background:#101620}.path{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#b7c2d4;font-size:13px}.dirty{display:none;width:8px;height:8px;border-radius:50%;background:var(--warn)}textarea{width:100%;height:100%;resize:none;border:0;outline:0;padding:18px 20px;background:#0b1017;color:#d9e2f0;font:14px/1.55 "SFMono-Regular",Consolas,"Liberation Mono",monospace;tab-size:4}.empty{display:grid;place-items:center;color:#66768c}.statusbar{display:flex;align-items:center;justify-content:space-between;padding:0 12px;border-top:1px solid var(--line);color:#6e7e95;font-size:11px;background:#0e141d}.git-state{display:flex;align-items:center;gap:7px}.dot{width:8px;height:8px;border-radius:50%;background:var(--ok)}.toast{position:fixed;right:20px;bottom:20px;min-width:270px;max-width:460px;background:#151e2a;border:1px solid #34445b;border-radius:12px;padding:13px 15px;box-shadow:0 20px 60px #0009;display:none;z-index:50}.toast.error{border-color:#6b3439;color:#ffc4c8}.commit{color:#98a7bc;font-size:12px;max-width:360px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(max-width:900px){.layout{grid-template-columns:190px 260px 1fr}}@media(max-width:720px){body{overflow:auto}.app{height:auto}.top{padding:12px}.actions{flex-wrap:wrap}.layout{display:block}.sidebar,.files{max-height:300px;border-right:0;border-bottom:1px solid var(--line)}.editor{height:70vh}}
</style></head><body><div class="app"><header class="top"><div class="brand"><div class="mark">1</div><div><h1>The One Dev Hub</h1><small>Android development control center</small></div></div><div class="actions"><span class="commit" id="latestCommit">Laden…</span><button class="btn" id="pullBtn">↻ Pull</button><button class="btn ok" id="saveBtn" disabled>Opslaan</button><button class="btn primary" id="pushBtn">Commit & Push</button></div></header><div class="layout"><aside class="sidebar"><div class="section-label">Projecten</div><button class="project active" data-project="app"><span class="ico">📱</span><span><strong>The One</strong><br><small style="color:var(--muted)">app/</small></span></button><button class="project" data-project="carradio"><span class="ico">🚗</span><span><strong>The One Car</strong><br><small style="color:var(--muted)">carradio/</small></span></button><div class="sidebar-footer"><div class="git-state"><span class="dot" id="gitDot"></span><span id="branch">main</span></div><div id="repoStatus" style="margin-top:7px">Git status laden…</div></div></aside><section class="files"><div class="crumb"><button class="btn" style="padding:5px 8px" id="upBtn">←</button><span id="crumb">app /</span></div><div id="fileList"></div></section><section class="editor"><div class="editor-head"><span class="dirty" id="dirty"></span><span class="path" id="openPath">Geen bestand geopend</span></div><div id="editorWrap" class="empty">Kies links een bestand om te bewerken.</div><div class="statusbar"><span id="fileMeta">—</span><span>UTF-8 • The One Dev Hub</span></div></section></div></div><div class="toast" id="toast"></div>
<script>
const CSRF=<?php echo json_encode($csrf,JSON_UNESCAPED_SLASHES);?>;let state={project:'app',dir:'',file:'',original:'',dirty:false};const $=s=>document.querySelector(s);function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast'+(error?' error':'');t.style.display='block';clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.style.display='none',3500)}async function api(action,opts={}){const method=opts.method||'GET';let url='api.php?action='+encodeURIComponent(action);if(opts.params)url+='&'+new URLSearchParams(opts.params);const init={method,headers:{Accept:'application/json'}};if(method!=='GET'){init.headers['Content-Type']='application/json';init.headers['X-CSRF-Token']=CSRF;init.body=JSON.stringify(opts.body||{})}const r=await fetch(url,init);const j=await r.json().catch(()=>({ok:false,error:'Ongeldige serverreactie'}));if(!r.ok||j.ok===false)throw new Error(j.error||('HTTP '+r.status));return j}function humanSize(n){if(n==null)return'';if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}async function loadStatus(){try{const j=await api('status');$('#branch').textContent=j.data.branch||'main';$('#latestCommit').textContent=j.data.commit||'';const clean=!j.data.status;$('#repoStatus').textContent=clean?'Working tree clean':'Wijzigingen aanwezig';$('#gitDot').style.background=clean?'var(--ok)':'var(--warn)'}catch(e){$('#repoStatus').textContent='Status fout';$('#gitDot').style.background='var(--danger)'}}async function listFiles(){try{const j=await api('list',{params:{project:state.project,path:state.dir}});$('#crumb').textContent=state.project+' / '+(state.dir?state.dir+'/':'');$('#fileList').innerHTML='';j.data.items.sort((a,b)=>(a.type===b.type?a.name.localeCompare(b.name):a.type==='folder'?-1:1)).forEach(it=>{const row=document.createElement('div');row.className='file-row '+(it.type==='folder'?'folder':'');row.innerHTML=`<span>${it.type==='folder'?'📁':'📄'}</span><span class="file-name"></span><span class="file-size">${humanSize(it.size)}</span>`;row.querySelector('.file-name').textContent=it.name;row.onclick=()=>it.type==='folder'?openDir(it.name):openFile(it.name);$('#fileList').appendChild(row)})}catch(e){toast(e.message,true)}}function openDir(name){state.dir=state.dir?state.dir+'/'+name:name;listFiles()}function up(){if(!state.dir)return;state.dir=state.dir.split('/').slice(0,-1).join('/');listFiles()}async function openFile(name){if(state.dirty&&!confirm('Niet-opgeslagen wijzigingen weggooien?'))return;const path=state.dir?state.dir+'/'+name:name;try{const j=await api('read',{params:{project:state.project,path}});state.file=path;state.original=j.data.content;state.dirty=false;$('#dirty').style.display='none';$('#saveBtn').disabled=false;$('#openPath').textContent=state.project+'/'+path;const ta=document.createElement('textarea');ta.value=j.data.content;ta.spellcheck=false;ta.oninput=()=>{state.dirty=ta.value!==state.original;$('#dirty').style.display=state.dirty?'inline-block':'none'};$('#editorWrap').className='';$('#editorWrap').innerHTML='';$('#editorWrap').appendChild(ta);$('#fileMeta').textContent=humanSize(new Blob([j.data.content]).size)}catch(e){toast(e.message,true)}}async function saveFile(){const ta=$('#editorWrap textarea');if(!ta||!state.file)return;try{await api('save',{method:'POST',body:{project:state.project,path:state.file,content:ta.value}});state.original=ta.value;state.dirty=false;$('#dirty').style.display='none';toast('Bestand opgeslagen');loadStatus()}catch(e){toast(e.message,true)}}async function pull(){try{const j=await api('pull',{method:'POST'});toast(j.data.output||'Pull voltooid');loadStatus();listFiles()}catch(e){toast(e.message,true)}}async function commitPush(){if(state.dirty){toast('Sla het geopende bestand eerst op.',true);return}const message=prompt('Commit message:','Update via The One Dev Hub');if(!message)return;try{const j=await api('commitpush',{method:'POST',body:{message}});toast(j.data.output||'Commit & push voltooid');loadStatus()}catch(e){toast(e.message,true)}}function switchProject(project){if(state.dirty&&!confirm('Niet-opgeslagen wijzigingen weggooien?'))return;state={project,dir:'',file:'',original:'',dirty:false};document.querySelectorAll('.project').forEach(b=>b.classList.toggle('active',b.dataset.project===project));$('#editorWrap').className='empty';$('#editorWrap').textContent='Kies links een bestand om te bewerken.';$('#openPath').textContent='Geen bestand geopend';$('#saveBtn').disabled=true;$('#dirty').style.display='none';listFiles()}document.querySelectorAll('.project').forEach(b=>b.onclick=()=>switchProject(b.dataset.project));$('#upBtn').onclick=up;$('#saveBtn').onclick=saveFile;$('#pullBtn').onclick=pull;$('#pushBtn').onclick=commitPush;window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});loadStatus();listFiles();
</script></body></html>